"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[24740],{24740:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/greenhouse-at-the-end-of-the-world.png\\"\\n          title=\\"Greenhouse at the End of the World\\"\\n          author=\\"Kim Cho-yeop\\"\\n          publisher=\\"Giant Books\\"\\n          publishedDate=\\"2021-08-18\\"\\n          isbn=\\"9791191824001\\"\\n          rating=3.5\\n          tags=\\"sf\\"\\n        />\\n</center>\\n\\n## Review\\nA story of a generation on the brink of extinction due to a lethal toxic nano-dust called ```Dust```.  \\nA common subject in SF is indeed the extinction of mankind.  \\nIf the production is possible, it seems like a material and fun element that could be made into a movie.  \\n<br>\\nThe duality of mankind in dealing with the <mark>resistant species</mark> that always appears in such stories is also revealed in this book.  \\nAre they beings that must be sacrificed for the sake of mankind and the public interest?"}')}}]);